### 4. 持久化存储
我们将使用 JSON 文件来持久化存储任务状态。

```python
import json

class TaskManager:
    def __init__(self, filename='tasks.json'):
        self.filename = filename
        self.load_tasks()

    def load_tasks(self):
        try:
            with open(self.filename, 'r') as f:
                self.tasks = json.load(f)
        except FileNotFoundError:
            self.tasks = {}

    def save_tasks(self):
        with open(self.filename, 'w') as f:
            json.dump(self.tasks, f)

    # 其他方法保持不变
```

### 5. 重启恢复流程
我们将使用一个定时器来定期检查任务状态，并恢复已执行的任务。

```python
import time
import threading

class TaskManager:
    def __init__(self, filename='tasks.json', max_retries=3, interval=60):
        self.filename = filename
        self.max_retries = max_retries
        self.interval = interval
        self.thread = threading.Thread(target=self.check_tasks, daemon=True)
        self.thread.start()

    def check_tasks(self):
        while True:
            self.load_tasks()
            for task_id, task in self.tasks.items():
                if task['status'] == '执行中':
                    continue
                if task['status'] == '未执行':
                    self.execute_task(task_id)
                elif task['status'] == '失败':
                    if self.tasks[task_id]['retry_count'] < self.max_retries:
                        self.execute_task(task_id)
                        self.tasks[task_id]['retry_count'] += 1
                    else:
                        self.tasks[task_id]['status'] = '已完成'
                self.save_tasks()
            time.sleep(self.interval)

    def execute_task(self, task_id):
        # 模拟任务执行
        self.tasks[task_id]['status'] = '执行中'
        self.tasks[task_id]['execution_time'] = time.time()
        # 模拟任务执行失败
        if random.random() < 0.5:
            self.tasks[task_id]['status'] = '失败'
            self.tasks[task_id]['retry_count'] = 0
        else:
            self.tasks[task_id]['status'] = '已完成'
            self.tasks[task_id]['retry_count'] = 0
        self.save_tasks()
```

